13	    expect(
14	      scoreArmy([
15	        { monster: "hydra" },
16	        { monster: "zombie" },
17	        { monster: "cyclops" },
18	        { monster: "orthrus" },
19	      ]),
20	    ).toBe(0);
21	  });
22	
23	  // --- A single Sphinx, three or fewer distinct types: 1 point each ---
24	  it("scores a lone Sphinx as 1 — one type is not beyond three", () => {
25	    expect(scoreArmy([{ monster: "sphinx" }])).toBe(1);
26	  });
27	  it("scores a Sphinx with two distinct types as 1 — sphinx, hydra is worth 1", () => {
28	    expect(scoreArmy([{ monster: "sphinx" }, { monster: "hydra" }])).toBe(1);
29	  });
30	  it("scores a Sphinx with exactly three distinct types as 1 — sphinx, hydra, zombie is worth 1", () => {
31	    expect(
32	      scoreArmy([
33	        { monster: "sphinx" },
34	        { monster: "hydra" },
35	        { monster: "zombie" },
36	      ]),
37	    ).toBe(1);
38	  });
39	
40	  // --- A single Sphinx, more than three distinct types: 2 per type beyond three ---
41	  it("scores a Sphinx with four distinct types as 2 — sphinx, hydra, zombie, cyclops is worth 2", () => {
42	    expect(
43	      scoreArmy([
44	        { monster: "sphinx" },
45	        { monster: "hydra" },
46	        { monster: "zombie" },
47	        { monster: "cyclops" },
48	      ]),
49	    ).toBe(2);
50	  });
51	  it("scores a Sphinx with five distinct types as 4 — sphinx, hydra, zombie, cyclops, orthrus is worth 4", () => {
52	    expect(
53	      scoreArmy([
54	        { monster: "sphinx" },
55	        { monster: "hydra" },
56	        { monster: "zombie" },
57	        { monster: "cyclops" },
58	        { monster: "orthrus" },
59	      ]),
60	    ).toBe(4);
