62	  it("scores a Sphinx with all seven distinct types as 8 — four types beyond three is worth 8", () => {
63	    expect(
64	      scoreArmy([
65	        { monster: "sphinx" },
66	        { monster: "undead-warrior", rank: 1 },
67	        { monster: "zombie" },
68	        { monster: "hydra" },
69	        { monster: "cyclops" },
70	        { monster: "orthrus" },
71	        { monster: "chimera" },
72	      ]),
73	    ).toBe(8);
74	  });
75	
76	  // --- Duplicates do not add types ---
77	  it("counts a repeated monster as a single type — sphinx, hydra, hydra, zombie is worth 1", () => {
78	    expect(
79	      scoreArmy([
80	        { monster: "sphinx" },
81	        { monster: "hydra" },
82	        { monster: "hydra" },
83	        { monster: "zombie" },
84	      ]),
85	    ).toBe(1);
86	  });
87	
88	  // --- Undead Warrior ranks are distinct types ---
89	  it("counts each Undead Warrior rank as its own type — sphinx, undead-warrior rank 1, rank 2, rank 3 is worth 2", () => {
90	    expect(
91	      scoreArmy([
92	        { monster: "sphinx" },
93	        { monster: "undead-warrior", rank: 1 },
